WITH prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC) AS prev_txn_time FROM transactions), flagged AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), sessions_transactions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY txn_type ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT id, account_id, amount, merchant, is_flagged FROM sessions_transactions ORDER BY account_id ASC NULLS LAST, amount ASC
